{
  "name": "tdd-experiment-run",
  "type": "module",
  "scripts": {
    "test": "vitest run",
    "test:unit:basic": "vitest run",
    "test:watch": "vitest",
    "test:coverage": "vitest run --coverage --coverage.reporter=json-summary"
  },
  "devDependencies": {
    "typescript": "^5.3.0",
    "tsx": "^4.7.0",
    "vitest": "^1.0.0",
    "@vitest/coverage-v8": "^1.0.0",
    "eslint": "^9.0.0",
    "eslint-plugin-sonarjs": "^1.0.0",
    "typescript-eslint": "^8.0.0"
  },
  "pnpm": {
    "onlyBuiltDependencies": ["esbuild"]
  }
}

1	export interface Card {
2	  monster: string;
3	  rank?: number;
4	}
5	
6	const TYPE_THRESHOLD = 3;
7	const POINTS_PER_TYPE_BEYOND_THRESHOLD = 2;
8	const BASE_POINTS = 1;
9	
10	const isSphinx = (card: Card): boolean => card.monster === "sphinx";
11	
12	// Undead Warriors of different ranks are different types; every other
13	// monster has a single variant, so its rank is absent and all its cards
14	// share one key.
15	const typeIdentityOf = (card: Card): string => `${card.monster}/${card.rank}`;
16	
17	const countDistinctTypes = (army: Card[]): number =>
18	  new Set(army.map(typeIdentityOf)).size;
19	
20	const pointsForEachSphinx = (distinctTypes: number): number => {
21	  const typesBeyondThreshold = distinctTypes - TYPE_THRESHOLD;
22	  return typesBeyondThreshold > 0
23	    ? POINTS_PER_TYPE_BEYOND_THRESHOLD * typesBeyondThreshold
24	    : BASE_POINTS;
25	};
26	
27	export const scoreArmy = (army: Card[]): number =>
28	  army.filter(isSphinx).length *
29	  pointsForEachSphinx(countDistinctTypes(army));
